def normalize(path):
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if absolute and stack:
                stack.pop()
            else:
                stack.append(part)
        else:
            stack.append(part)
    if absolute:
        return '/' if not stack else '/' + '/'.join(stack)
    else:
        return '.' if not stack else '/'.join(stack)
```

