def deep_get(obj, path, default=None):
    if path is None:
        return default

    parts = path.split('.')
    current = obj

    for part in parts:
        if current is None:
            return default

        if isinstance(current, list):
            try:
                index = int(part)
                if 0 <= index < len(current):
                    current = current[index]
                else:
                    return default
            except (ValueError, TypeError):
                return default
        elif isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return default
        else:
            return default

    return current
```

