import heapq

def topk(items, k):
    if k <= 0:
        return []
    heap = []
    for item in items:
        if len(heap) < k:
            heapq.heappush(heap, item)
        elif item > heap[0]:
            heapq.heapreplace(heap, item)
    result = []
    while heap:
        result.append(heapq.heappop(heap))
    result.reverse()
    return result
```

