def strip_comments(code):
    result = []
    in_string = False
    i = 0
    n = len(code)

    while i < n:
        char = code[i]

        if char == '#':
            if not in_string:
                # It is a comment. Skip to the end of the line.
                while i < n and code[i] != '\n':
                    i += 1
            else:
                # It is inside a string. Keep it.
                result.append(char)
        elif char in ('"', "'"):
            # Check if the quote is escaped by a backslash
            if i > 0 and code[i-1] == '\\':
                # Escaped quote, append and do not toggle state
                result.append(char)
            else:
                # Toggle string state
                in_string = not in_string
        else:
            # Normal character
            result.append(char)

        i += 1

    return ''.join(result)
```

