import hashlib

def stable_hash(obj):
    def serialize(o):
        if isinstance(o, dict):
            items = [f"{serialize(k)}: {serialize(o[k])}" for k in sorted(o, key=serialize)]
            return "{" + ", ".join(items) + "}"
        elif isinstance(o, list):
            return "[" + ", ".join(serialize(x) for x in o) + "]"
        elif isinstance(o, str):
            return repr(o)
        elif isinstance(o, int):
            return repr(o)
        else:
            return repr(o)
    return hashlib.sha256(serialize(obj).encode('utf-8')).hexdigest()
```

