function deepEqual(a, b) {
    // Check for strict equality (handles primitives and same reference objects)
    if (a === b) {
        return true;
    }

    // Check if either is null or not an object (primitives after first check)
    if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) {
        return false;
    }

    // Determine if they are arrays
    const isArrayA = Array.isArray(a);
    const isArrayB = Array.isArray(b);

    // Arrays and Objects are different types
    if (isArrayA !== isArrayB) {
        return false;
    }

    // Get keys to compare (handles key order irrelevance)
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) {
        return false;
    }

    // Check every key exists in both and values are deeply equal
    for (let i = 0; i < keysA.length; i++) {
        const key = keysA[i];

        // Check key existence in b
        if (!Object.prototype.hasOwnProperty.call(b, key)) {
            return false;
        }

        // Recursively compare values
        if (!deepEqual(a[key], b[key])) {
            return false;
        }
    }

    return true;
}

module.exports = deepEqual;

