function flattenObject(obj) {
  const result = {};

  function flatten(current, prefix) {
    Object.entries(current).forEach(([key, value]) => {
      const newKey = prefix ? `${prefix}.${key}` : key;

      if (
        typeof value === "object" &&
        value !== null &&
        !Array.isArray(value)
      ) {
        flatten(value, newKey);
      } else {
        result[newKey] = value;
      }
    });
  }

  flatten(obj);
  return result;
}

module.exports = flattenObject;

