            clearTimeout(timer);
        }
        timer = setTimeout(flush, ms);
    };

    const flush = () => {
        if (timer) {
            clearTimeout(timer);
            timer = null;
        }
        const result = fn(count);
        count = 0;
        return result;
    };

    return { call, flush };
}

module.exports = debounceCount;
