function mergeDeep(a, b) {
  // Create a shallow copy of a to ensure we do not mutate the original 'a' object.
  // This handles primitive arrays correctly using slice().
  const result = Array.isArray(a) ? a.slice() : { ...a };

  // Iterate over all enumerable properties in b
  for (const key in b) {
    if (b.hasOwnProperty(key)) {
      const sourceVal = b[key];
      const targetVal = result[key];

      // If both values are objects (and not arrays/null), recursively merge them.
      if (
        typeof sourceVal === 'object' &&
        sourceVal !== null &&
        !Array.isArray(sourceVal) &&
        typeof targetVal === 'object' &&
        targetVal !== null &&
        !Array.isArray(targetVal)
      ) {
        // Recursively merge the nested objects
        result[key] = mergeDeep(targetVal, sourceVal);
      } else {
        // If not both are objects, overwrite the value in the copy with the value from b.
        // This does not mutate b, and assigns a new reference in the result object.
        result[key] = sourceVal;
      }
    }
  }

  return result;
}

module.exports = mergeDeep;
```

