function rotateArray(arr, k) {
  if (!arr || arr.length === 0) {
    return [];
  }

  const n = arr.length;

  // Handle negative k and k larger than array length
  k = k % n;

  if (k < 0) {
    k += n;
  }

  // Return a copy of the array rotated to the right
  const rotated = arr.slice(-k).concat(arr.slice(0, n - k));
  return rotated;
}

module.exports = rotateArray;
