import React, { useState, useCallback } from 'react';
import { View, Text, StyleSheet, Button } from 'react-native';

const ChildComponent = ({ onMessage }) => {
  // Simulate that this component would re-render if 'onMessage' reference changes
  return (
    <View style={styles.childBox}>
      <Text>Child Component</Text>
      <Button title="Click Me" onPress={onMessage} />
    </View>
  );
};

const ParentComponent = () => {
  const [count, setCount] = useState(0);

  // Using useCallback to keep the function reference stable across parent renders
  // as long as its dependencies (here none) do not change.
  const handleClick = useCallback(() => {
    console.log('Handler executed');
    setCount((prev) => prev + 1);
  }, []);

  return (
    <View style={styles.container}>
      <Text style={styles.text}>Parent Count: {count}</Text>

      {/* Passing the stable handler to the child */}
      <ChildComponent onMessage={handleClick} />

      <Button 
        title="Re-render Parent (Identity Stable)" 
        onPress={() => setCount((prev) => prev + 1)} 
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  childBox: {
