  const [loading, setLoading] = useState(false);

  const handlePress = async () => {
    setLoading(true);

    const supported = await Linking.canOpenURL(url);

    if (supported) {
      try {
        await Linking.openURL(url);
      } catch (error) {
        Alert.alert(`Error opening url: ${error.message}`);
