import React, { useRef, useState } from 'react';
import { View, Text, Button } from 'react-native';

const RefExample = () => {
  // State value that triggers a re-render when changed
  const [count, setCount] = useState(0);

  // Ref value that persists across renders without triggering a re-render
  const ref = useRef(0);

  const handleStateUpdate = () => {
    setCount((prev) => prev + 1);
  };

  const handleRefUpdate = () => {
    ref.current += 1;
    // Updating ref.current does NOT cause this component to re-render
  };

  return (
    <View style={{ alignItems: 'center', marginTop: 50 }}>
      <Text style={{ fontSize: 24, fontWeight: 'bold' }}>State Count: {count}</Text>
      <Text style={{ fontSize: 24, color: 'red', fontWeight: 'bold' }}>Ref Count: {ref.current}</Text>
      <View style={{ marginTop: 20 }}>
        <Button title="Update State (Re-render)" onPress={handleStateUpdate} />
      </View>
      <View style={{ marginTop: 10 }}>
        <Button title="Update Ref (No Re-render)" onPress={handleRefUpdate} />
      </View>
    </View>
  );
};

export default RefExample;
```

